import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import { Editor } from "@tinymce/tinymce-react";
import api from "../api";

const ManageBook = () => {
  const { bookId } = useParams();
  const [chapters, setChapters] = useState([]);
  const [newChapterTitle, setNewChapterTitle] = useState("");
  const [editorValue, setEditorValue] = useState("");
  const [newChapterContent, setNewChapterContent] = useState("");

  useEffect(() => {
    const fetchChapters = async () => {
      try {
        const response = await api.get(`/api/books/${bookId}/chapters`);
        setChapters(response.data.chapters);
      } catch (err) {
        console.error("Error fetching chapters:", err);
      }
    };
    fetchChapters();
  }, [bookId]);

  const handleAddChapter = async () => {
    try {
      const response = await api.post(
        `/api/books/${bookId}/chapters`,
        {
          title: newChapterTitle,
          content: newChapterContent,
        },
        {
          headers: { Authorization: `Bearer ${localStorage.getItem("token")}` },
        }
      );

      // Refresh chapter list
      setChapters([...chapters, response.data]);
      setNewChapterTitle("");
      setNewChapterContent("");
    } catch (err) {
      console.error("Error adding chapter:", err);
    }
  };

  const onEditorInputChange = (newValue, editor) => {
    setEditorValue(newValue);
    setNewChapterContent(editor.getContent({ format: "text" }));
  };
  return (
    <div className="manage-book">
      <h2>Manage Book</h2>
      <h3>Chapters</h3>
      <ul>
        {chapters.map((chapter) => (
          <h4>
            {chapter.title},{chapter.content}
          </h4>
        ))}
      </ul>

      <h3>Add a New Chapter</h3>
      <input
        type="text"
        value={newChapterTitle}
        onChange={(e) => setNewChapterTitle(e.target.value)}
        placeholder="Chapter Title"
        required
      />
      <textarea
        value={newChapterContent}
        onChange={(e) => setNewChapterContent(e.target.value)}
        placeholder="Chapter Content"
        required
      ></textarea>
      <Editor
        apiKey="88pb83a1e7lg1vuj66gj6osihy71r5ebdtldqvohimk45a8s"
        init={{ plugins: "fullscreen", toolbar: "fullscreen" }}
        onEditorChange={(newValue, editor) =>
          onEditorInputChange(newValue, editor)
        }
        onInit={(evt, editor) =>
          setNewChapterContent(editor.getContent({ format: "text" }))
        }
        value={editorValue}
        initialValue={"Start writing..."}
      />
      <button onClick={handleAddChapter}>Add Chapter</button>
    </div>
  );
};

export default ManageBook;
